def first_bad_fold(scores, baseline, k):
    """Index (0-based) of the first fold that starts a run of k
    consecutive scores strictly below baseline; None if there is none."""
    run = 0
    for i, s in enumerate(scores):
        run = run + 1 if s < baseline else 0
        if run == k:
            return i - k + 1
    return None
